(4133,3,252,'Circular flow of income refers to:','[\"Flow of goods only\",\"Flow of money only\",\"Continuous flow of money, goods and services between sectors\",\"Flow of exports only\"]','[\"Continuous flow of money, goods and services between sectors\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4134,3,252,'In a two-sector economy, the two sectors are:','[\"Government and foreign sector\",\"Household and firms\",\"Banks and firms\",\"Government and banks\"]','[\"Household and firms\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4135,3,252,'Which of the following is an example of a final good?','[\"Milk used by a bakery\",\"Steel used in car production\",\"Bread bought by a family\",\"Cotton used in textile mills\"]','[\"Bread bought by a family\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4136,3,252,'Stock is measured:','[\"Over a period of time\",\"At a specific point of time\",\"Weekly only\",\"Monthly only\"]','[\"At a specific point of time\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4137,3,252,'Investment means:','[\"Buying consumer goods\",\"Addition to stock of capital goods\",\"Spending on food items\",\"Spending on imports\"]','[\"Addition to stock of capital goods\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4138,3,252,'Net Investment is equal to:','[\"Gross investment + depreciation\",\"Gross investment - depreciation\",\"Depreciation - gross investment\",\"Gross investment × depreciation\"]','[\"Gross investment - depreciation\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4139,3,252,'National Income includes:','[\"Only income earned inside the country\",\"Only income from foreign countries\",\"Income earned domestically and net factor income from abroad\",\"Transfer payments\"]','[\"Income earned domestically and net factor income from abroad\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4140,3,252,'GDP measures:','[\"Income earned only abroad\",\"Value of final goods produced within domestic territory\",\"Only agricultural output\",\"Income earned by foreigners only\"]','[\"Value of final goods produced within domestic territory\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4141,3,252,'Which of the following is included in the expenditure method?','[\"Rent\",\"Interest\",\"Government expenditure\",\"Profit\"]','[\"Government expenditure\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4142,3,252,'Which of the following is a difficulty in national income estimation?','[\"Too much data availability\",\"Double counting of intermediate goods\",\"Excess labour supply\",\"High productivity\"]','[\"Double counting of intermediate goods\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4143,3,252,'GDP = Rs.1000 crore and Depreciation =Rs.100 crore. NDP equals:','[\"900 crore\",\"1100 crore\",\"100 crore\",\"1200 crore\"]','[\"900 crore\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4144,3,252,'If GDP =Rs. 5000 crore and NFIA = Rs. 200 crore, then GNP equals:','[\"4800 crore\",\"5200 crore\",\"5000 crore\",\"5300 crore\"]','[\"5200 crore\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4145,3,252,'Which formula correctly represents Net National Product?','[\"NNP = GDP + Depreciation\",\"NNP = GDP − Depreciation + NFIA\",\"NNP = GDP − NFIA\",\"NNP = GDP + Taxes\"]','[\"NNP = GDP − Depreciation + NFIA\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4146,3,252,'National Income is equal to:','[\"NNP at Market Price\",\"GDP at Market Price\",\"NNP at Factor Cost\",\"GNP at Market Price\"]','[\"NNP at Factor Cost\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4147,3,252,'If GDP = Rs.2000 crore and Depreciation = Rs.200 crore, NFIA = Rs.100 crore, then NNP equals','[\"1900 crore\",\"1800 crore\",\"2100 crore\",\"1700 crore\"]','[\"1900 crore\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4148,3,252,'A tyre produced in a factory is counted once during production and again when included in the price of a car. This problem is known as:','[\"Transfer payment\",\"Double counting\",\"Inflation\",\"Black money\"]','[\"Double counting\"]',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
