(4647,2,240,'Match each line of the segmentation address-translation pseudocode with what it computes.','{\"Segment = (VirtualAddress & SEG_MASK) >> SEG_SHIFT\":\"Extracts the top bits to identify which segment is being accessed\",\"Offset = VirtualAddress & OFFSET_MASK\":\"Extracts the byte offset within the identified segment\",\"PhysAddr = Base[Segment] + Offset\":\"Computes the final physical address by adding segment base to offset\"}','{\"Segment = (VirtualAddress & SEG_MASK) >> SEG_SHIFT\":\"Extracts the top bits to identify which segment is being accessed\",\"Offset = VirtualAddress & OFFSET_MASK\":\"Extracts the byte offset within the identified segment\",\"PhysAddr = Base[Segment] + Offset\":\"Computes the final physical address by adding segment base to offset\"}',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
(4648,2,240,'Match each segmentation feature with its description.','{\"Protection bits\":\"Per-segment flags indicating read, write, or execute permissions\",\"Code sharing\":\"Mapping the same read-only physical segment into multiple virtual address spaces\",\"Fine-grained segmentation\":\"An approach (e.g., Multics) allowing a very large number of small segments using a segment table\"}','{\"Protection bits\":\"Per-segment flags indicating read, write, or execute permissions\",\"Code sharing\":\"Mapping the same read-only physical segment into multiple virtual address spaces\",\"Fine-grained segmentation\":\"An approach (e.g., Multics) allowing a very large number of small segments using a segment table\"}',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,4),
