(5512,2,211,'Match each line of the segmentation address-translation pseudocode with what it computes.','{\"Segment = (VirtualAddress & SEG_MASK) >> SEG_SHIFT\":\"Extracts the top bits to identify which segment is being accessed\",\"Offset = VirtualAddress & OFFSET_MASK\":\"Extracts the byte offset within the identified segment\",\"PhysAddr = Base[Segment] + Offset\":\"Computes the final physical address by adding segment base to offset\"}','{\"Segment = (VirtualAddress & SEG_MASK) >> SEG_SHIFT\":\"Extracts the top bits to identify which segment is being accessed\",\"Offset = VirtualAddress & OFFSET_MASK\":\"Extracts the byte offset within the identified segment\",\"PhysAddr = Base[Segment] + Offset\":\"Computes the final physical address by adding segment base to offset\"}',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,2),
